window.ScripturaLexicons.BDAG_PART_0258 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-01\" data-source=\"BDAG\" data-search=\"ὄπυσις, εως, ἡ substantivo feminino possível fornicação; leitura contestada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄπυσις, εως, ἡ</td><td>substantivo feminino</td><td>possível fornicação; leitura contestada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-02\" data-source=\"BDAG\" data-search=\"ὀπώρα, ας, ἡ substantivo feminino época dos frutos; fruto maduro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπώρα, ας, ἡ</td><td>substantivo feminino</td><td>época dos frutos; fruto maduro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-03\" data-source=\"BDAG\" data-search=\"ὅπως advérbio/conjunção como; que; para que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅπως</td><td>advérbio/conjunção</td><td>como; que; para que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-04\" data-source=\"BDAG\" data-search=\"ὅραμα, ατος, τό substantivo neutro visão; algo visto; manifestação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅραμα, ατος, τό</td><td>substantivo neutro</td><td>visão; algo visto; manifestação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-05\" data-source=\"BDAG\" data-search=\"ὅρασις, εως, ἡ substantivo feminino olho; aparência; visão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅρασις, εως, ἡ</td><td>substantivo feminino</td><td>olho; aparência; visão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-06\" data-source=\"BDAG\" data-search=\"ὁρατός, ή, όν adjetivo visível; perceptível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁρατός, ή, όν</td><td>adjetivo</td><td>visível; perceptível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-07\" data-source=\"BDAG\" data-search=\"ὁράω verbo ver; perceber; aparecer; visitar; vigiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁράω</td><td>verbo</td><td>ver; perceber; aparecer; visitar; vigiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-08\" data-source=\"BDAG\" data-search=\"ὄργανον, ου, τό substantivo neutro instrumento; ferramenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄργανον, ου, τό</td><td>substantivo neutro</td><td>instrumento; ferramenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-09\" data-source=\"BDAG\" data-search=\"ὀργή, ῆς, ἡ substantivo feminino ira; indignação; juízo punitivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀργή, ῆς, ἡ</td><td>substantivo feminino</td><td>ira; indignação; juízo punitivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-10\" data-source=\"BDAG\" data-search=\"ὀργίζω verbo irar-se; ficar indignado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀργίζω</td><td>verbo</td><td>irar-se; ficar indignado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-11\" data-source=\"BDAG\" data-search=\"ὀργίλος, η, ον adjetivo irascível; colérico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀργίλος, η, ον</td><td>adjetivo</td><td>irascível; colérico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-12\" data-source=\"BDAG\" data-search=\"ὀργίλως advérbio iradamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀργίλως</td><td>advérbio</td><td>iradamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-13\" data-source=\"BDAG\" data-search=\"ὀργυιά substantivo feminino braça; medida de profundidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀργυιά</td><td>substantivo feminino</td><td>braça; medida de profundidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-14\" data-source=\"BDAG\" data-search=\"ὀρέγω verbo aspirar a; desejar; esforçar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρέγω</td><td>verbo</td><td>aspirar a; desejar; esforçar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-15\" data-source=\"BDAG\" data-search=\"ὀρεινός, ή, όν adjetivo montanhoso; região de colinas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρεινός, ή, όν</td><td>adjetivo</td><td>montanhoso; região de colinas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-16\" data-source=\"BDAG\" data-search=\"ὄρεξις, εως, ἡ substantivo feminino desejo; anseio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄρεξις, εως, ἡ</td><td>substantivo feminino</td><td>desejo; anseio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-17\" data-source=\"BDAG\" data-search=\"ὀρθοποδέω verbo andar corretamente; proceder com retidão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθοποδέω</td><td>verbo</td><td>andar corretamente; proceder com retidão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-18\" data-source=\"BDAG\" data-search=\"ὀρθός, ή, όν adjetivo reto; ereto; correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθός, ή, όν</td><td>adjetivo</td><td>reto; ereto; correto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-19\" data-source=\"BDAG\" data-search=\"ὀρθοτομέω verbo abrir caminho reto; conduzir corretamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθοτομέω</td><td>verbo</td><td>abrir caminho reto; conduzir corretamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0258-20\" data-source=\"BDAG\" data-search=\"ὀρθόω verbo endireitar; erguer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρθόω</td><td>verbo</td><td>endireitar; erguer</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0258-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄπυσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄπυσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (hápax, derivado de <span class=\"greek\">ὀπυίω</span>, originalmente «casar-se»; no grego posterior, «ter relações íntimas com uma mulher», Luc., Eun. 12), talvez = fornicação (CWessely, PatrOr 18, 1924, 482, e KPrümm, Biblica 10, 1929, 62–80): <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">ἄρχουσαν</span> <span class=\"greek\">ὁπύσεως</span>, numa cidade (isto é, Roma) que preside à prostituição/fornicação, ApcPt Rainer 4, 1 p. 278 J. (leitura do manuscrito; James, porém, propõe conjecturalmente na p. 273, com base na versão etíope, <span class=\"greek\">δύσεως</span>, «[governa] o Ocidente»).—DELG s.v. <span class=\"greek\">ὀπυίω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπώρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπώρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>, propriamente a época que começa com o aparecimento da estrela Sírio (em julho), correspondente ao fim do verão e início do outono, quando os frutos amadurecem (assim Hom. e outros); depois, o próprio fruto (assim os trágicos, X., Pla. e outros; POxy 298, 38 [I d.C.]; PGM 5, 231; Jer 31:32; 47:10, 12; TestIss 3:6; JosAs 4:4; Philo, Agr. 15; Jos., Bell. 3, 49; empréstimo na literatura rabínica): <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπιθυμίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, o fruto por que tua alma ansiava, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:14</a>.—B. 375. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅπως</h1><div class=\"entry-meta\"><span>advérbio/conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅπως</span> (Hom. e posteriores). ① Como advérbio marcador do modo como um acontecimento se desenvolve, como, de que maneira, que (B-D-F § 300, 1; Rob. 985), com indicativo aoristo (Jos., Bell. 1, 6; 17): <span class=\"greek\">ὅπως</span> <span class=\"greek\">τε</span> <span class=\"greek\">παρέδωκαν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρχιερεῖς</span>, como os principais sacerdotes o entregaram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:20</a>; com indicativo presente (Pherecrates Com. [V a.C.], Fgm. 45 K.; Tat. 22, 2 <span class=\"greek\">ὅπως</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">μοιχεύειν</span>): <span class=\"greek\">ὅπως</span> <span class=\"greek\">κολάζονται</span>, como são castigados, 2 Cl 17:7. Aqui, porém, o significado de <span class=\"greek\">ὅπως</span> provavelmente manifesta desenvolvimento análogo ao de <span class=\"greek\">πῶς</span> na linguagem coloquial, aproximando-se de <span class=\"greek\">ὡς</span> (assim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:20</a> D) = <span class=\"greek\">ὅτι</span> = que (X., Hier. 9, 1; Diod S 11, 46, 3; Lucian, Dial. Deor. 6, 2; BGU 846, 16 [II d.C.] <span class=\"greek\">γνοῦναι</span>, <span class=\"greek\">ὅπως</span> <span class=\"greek\">ὀφείλω</span> = «saber que devo»; Dssm., LO 155, 26 [LAE 179, 28]; B-D-F § 396; ver Rob. 1045). ② Como conjunção marcadora da finalidade de um evento ou estado, para que, a fim de que, com subjuntivo (a transição de 1 para 2 pode ser observada em SIG 741, 23), predominantemente aoristo (o indicativo futuro [desde Homero; frequente no V a.C. e depois: Andocides 1, 43; Demosth. 19, 316; Herodas 7, 90; ver Meisterhans 3-Schw. 255, 32; Nicol. Dam.: 90 Fgm. 16 p. 398, 5 Jac.; Hero Alex. I 368, 23 <span class=\"greek\">ὅπ</span>. <span class=\"greek\">κινήσει</span>; TestAbr B 1 p. 105, 4=Stone p. 58; TestJob 18:2; Jos., Ant. 11, 101] aparece como variante de leitura em vários lugares [por exemplo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:59</a>], mas provavelmente deveria ser corrigido em todos para subjuntivo aoristo). ⓐ Com numerosos tipos de verbos, para que, negativamente <span class=\"greek\">ὅπ</span>. <span class=\"greek\">μή</span>, para que … não (B-D-F § 369; Rob. 985–87). <span class=\"greek\">α</span>. Sem <span class=\"greek\">ἄν</span> (regra geral), após presente (ApcSed 16:2; Ar. 9:6; Just., A I, 47, 6 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:45</a> (imperativo); 6:2, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:9</a>; 2 Cl 9:6. Após perfeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a> (com <span class=\"greek\">μή</span>). Após imperfeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:24</a>. Após aoristo, versículos 2, 12; 20:16 (com <span class=\"greek\">μή</span>); 25:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:17ab</a> (Ex 9:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:29</a> (com <span class=\"greek\">μή</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:4</a>; 1 Cl 10:2; 35:4; após imperativo aoristo (TestAbr B 13 p. 117, 12 [Stone p. 82]; TestReub 1:4; JosAs 24:5; após particípio aoristo, Demetr.: 722 Fgm. 1, 1 Jac.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>; 5:16; 6:4, 18 (com <span class=\"greek\">μή</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:15</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a> (aqui se deve subentender <span class=\"greek\">γένηται</span> ou <span class=\"greek\">ᾖ</span> como predicado da oração com <span class=\"greek\">ὅπως</span>); GJs 21:2, códices; AcPlCor 2:16. Após mais-que-perfeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:57</a> (<span class=\"greek\">ὅπως</span> ocorre apenas aqui em J, talvez por motivo de variedade, já que <span class=\"greek\">ἵνα</span> aparece poucas palavras antes). Após futuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a>. Em conformidade com o propósito divino revelado nas Escrituras, um acontecimento pode ser introduzido pela fórmula (isto ou aquilo aconteceu) <span class=\"greek\">ὅπ</span>. <span class=\"greek\">πληρωθῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥηθὲν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">προφητῶν</span> (e expressões semelhantes), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 8:17; 12:17, variante de leitura; 13:35.—Alternando com <span class=\"greek\">ἵνα</span> (ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:57</a> acima), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:27f</a> (a oração com <span class=\"greek\">ἵνα</span> apresenta o conteúdo do pedido; a oração com <span class=\"greek\">ὅπως</span>, o propósito da dádiva solicitada; também Ex 23:20; TestAbr B 10 p. 114, 10 [Stone p. 76]; ApcMos 29; Just., D. 108, 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11f</a> (a oração com <span class=\"greek\">ἵνα</span> exprime o conteúdo, e a com <span class=\"greek\">ὅπως</span>, a finalidade da oração). <span class=\"greek\">β</span>. Com <span class=\"greek\">ἄν</span> e subjuntivo aoristo (B-D-F § 369, 5; Rdm. 2 194; Rob. 986; EHermann, Die Nebensätze in d. griech. Dialekten 1912, 276f; JKnuenz, De enuntiatis Graecorum finalibus 1913, 13ff; 26ff; Meisterhans 3-Schw. 254; Mayser II/1 p. 254f.—X., Cyr. 8, 3, 6 <span class=\"greek\">ἐπιμεληθῆναι</span> <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">οὕτω</span> <span class=\"greek\">γένηται</span>; Pla., Gorg. 523d; PSI 435, 19 [258 a.C.]; 438, 19; PMagd 23, 7; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:5</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:20</a>; 15:17 (Am 9:12, variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a> (Ps 50:6). ⓑ Substituindo cada vez mais o infinitivo após verbos de pedir que (B-D-F § 392, 1): <span class=\"greek\">αἰτέομαι</span> (Jos., Ant. 19, 288), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:3</a>; <span class=\"greek\">δέομαι</span> (Ps.-Aeschines, Ep. 3, 1; ParJer 7, 24; 32; ApcMos 9 e outros; Jos., Ant. 7, 191; 9, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a> (com <span class=\"greek\">μή</span>); <span class=\"greek\">ἐρωτάω</span> (PTebt 409, 4ff [5 d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:3</a>; 11:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:20</a>; <span class=\"greek\">παρακαλέω</span> (Jos., Ant. 8, 143), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:34</a> (variante <span class=\"greek\">ἵνα</span>); <span class=\"greek\">προσεύχομαι</span> ou <span class=\"greek\">εὔχομαι</span> (cf. PGM 3, 107; Jon 1:6; Jos., Ant. 11, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:16</a>. Talvez também Phlm 6, onde <span class=\"greek\">ὅπ</span>. poderia ser interpretado como dependente de <span class=\"greek\">προσεύχομαι</span>, inferido do sentido do versículo 4, a menos que <span class=\"greek\">ὅπως</span> aqui = <span class=\"greek\">ὥστε</span> (Archimed. I p. 16, 18 Heiberg <span class=\"greek\">ὅπως</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπίταγμα</span> e outros).—Do mesmo modo, após verbos de decidir (LXX): <span class=\"greek\">συμβούλιον</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">ὅπ</span>., resolver fazer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:14</a>; 22:15 (D <span class=\"greek\">πῶς</span>), onde muitos estudiosos preferem a tradução «deliberar com o objetivo de». Também <span class=\"greek\">συμβούλιον</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">ὅπ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:6</a>.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅραμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅραμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὁράω</span>; X. e outros), em nossa literatura, sobre visões extraordinárias, quer a pessoa que as experimenta esteja dormindo, quer esteja acordada. ① Aquilo que é percebido pelos olhos, algo visto, vista, visão (segundo Artem. 1, 2 p. 5, 19, <span class=\"greek\">ὅραμα</span> é algo que pode realmente ser visto, em contraste com 5, 17 <span class=\"greek\">φάντασμα</span> = produto da imaginação; PCairGoodsp 3, 5 [III a.C.]; PParis 51, 38 [160 a.C.]=UPZ 78 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὅραμα</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">τεθέαμαι</span>; Ex 3:3; Dt 4:34; Da 7:1; En 99:8; TestAbr A 4 p. 81, 13 [Stone p. 10] <span class=\"greek\">ἀναγγελεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὅραμα</span>; TestLevi 8:1 <span class=\"greek\">εἶδον</span> <span class=\"greek\">ὅραμα</span>; 9:2), acerca da Transfiguração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:9</a>. Da manifestação de Deus na sarça ardente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:31</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:17</a>, 19; 11:5; 12:9; 16:9f (Appian, Bell. Civ. 4, 134 §565: Bruto, prestes a atravessar <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἀσίας</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Εὐρώπην</span>, da Ásia para a Europa, durante a noite (<span class=\"greek\">νυκτός</span>) vê algo que se lhe apresenta [<span class=\"greek\">ὄψιν</span> <span class=\"greek\">ἰδεῖν</span>]: um <span class=\"greek\">φάσμα</span> — não um ser humano, nem um deus, mas um <span class=\"greek\">δαίμων</span> <span class=\"greek\">κακός</span>, um espírito mau — coloca-se ao seu lado e lhe dirige a palavra; cf. Philostrat., Life of Apollonius 4, 34, acerca de uma mudança de planos motivada por um sonho [<span class=\"greek\">ὄναρ</span>]); Hv 4, 2, 2. <span class=\"greek\">ἐπιδεικνύναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ὅραμα</span>, mostrar uma visão a alguém, 3, 2, 3. <span class=\"greek\">δεικνύναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ὁράματα</span> (com <span class=\"greek\">ἀποκαλύψεις</span>), mostrar visões a alguém, 4, 1, 3. <span class=\"greek\">ἀποκαλύπτειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁράματα</span>, revelar as visões (duplo sentido, como no original, que pode referir-se às próprias visões ou à interpretação de seu significado), 3, 4, 3. ② Ato pelo qual alguém recebe uma visão, ou estado em que se encontra quem a recebe, visão (SIG 1128 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅραμα</span>; LXX), acerca do Senhor: <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νυκτὶ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ὁράματος</span>, dizer à noite mediante uma visão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:9</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁράματι</span> (Gen 15:1; 46:2 <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span>; Da 7:13), <span class=\"greek\">εἶδεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ἄγγελον</span>, viu um anjo em visão (cf. TestJud 3:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:3</a>. Cf. 9:10, 12. <span class=\"greek\">βλέπειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span>, ver durante uma visão noturna, Hv 3, 10, 6. [<span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδὸ</span>] <span class=\"greek\">τ̣ο̣υ̣</span> [<span class=\"greek\">διελ</span>]<span class=\"greek\">θόντο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁρό</span>(=<span class=\"greek\">ά</span>)<span class=\"greek\">ματι</span> <span class=\"greek\">διὰ</span> [<span class=\"greek\">τοῦ</span> <span class=\"greek\">κεκλεισμένου</span>] <span class=\"greek\">κοιτῶ̣</span>[<span class=\"greek\">νο</span>], [o jovem] que em visão (de Paulo) entrou no quarto [fechado], AcPl Ha 5, 31f. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁράματι</span> <span class=\"greek\">ἰδ</span>[<span class=\"greek\">ούση</span>] <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, tendo visto o Senhor em visão, Ox 3525, 19. Ox 1224 Fgm. 2 anverso, II, 3 (=Kl. T. 8 3, p. 26, 10): <span class=\"greek\">Ἰῆ</span> [<span class=\"greek\">ἐ</span>]<span class=\"greek\">ν</span> <span class=\"greek\">ὁράμα</span>[<span class=\"greek\">τι</span> <span class=\"greek\">λέγει</span>]. Ver <span class=\"greek\">ὅρασις</span> 3, <span class=\"greek\">ὄναρ</span> e <span class=\"greek\">πνεῦμα</span> 6f.—DELG s.v. <span class=\"greek\">ὁράω</span>. M-M. TW. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅρασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅρασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁράω</span>; Aristot. e posteriores; inscrições, papiros, LXX, En; PsSol 6:3; TestAbr A 4 p. 80, 27 [Stone p. 8]; Test12 Patr; JosAs 18 [p. 68, 13 Bat.]; GrBar 4:3; AscIs 3, 13, 31; EpArist 142; Philo). ① Órgão da visão, olho (principalmente no plural «olhos», Diod S 2, 6, 10; Plut., Mor. 88d; PGM 13, 582; mas também no singular <span class=\"greek\">ὅρασις</span>, Diod S 3, 37, 9; 5, 43, 1; Proclus sobre Pla., Cratyl. p. 7, 25 Pasqu.; Iren. 1, 18, 1 [Harv. I, 171, 1]; Orig., C. Cels. 1, 48, 31; Hippol., Ref. 6, 15, 1), e, por extensão, vista, aparência, rosto (CB I/2, 653 nº 564 <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅρασιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>; PGM 4, 308; 5, 147; Sir 11:2; 25:17; 3 Macc 5:33), figuradamente, sobre a percepção mental e espiritual: <span class=\"greek\">ἀχλύος</span> <span class=\"greek\">γέμοντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁράσει</span>, com os olhos cheios de névoa, 2 Cl 1:6. ② Aquilo que é visto, aparência, vista. ⓐ Aparência (Philo Mech. 51, 10; 62, 23; Ezk 1:5; 1 Km 16:12; Hippol., Ref. 4, 20, 1): <span class=\"greek\">ὅμοιος</span> <span class=\"greek\">ὁράσει</span> <span class=\"greek\">λίθῳ</span> <span class=\"greek\">ἰάσπιδι</span>, semelhante em aparência a uma pedra de jaspe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3a</a>; cf. versículo 3b. ⓑ Espetáculo: <span class=\"greek\">ἔσονται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅρ</span>. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">σαρκί</span>, serão espetáculo para toda carne (Is 66:24), 2 Cl 7:6; 17:5. ③ Visão em modalidade transcendente (nesse caso, a distinção feita entre <span class=\"greek\">ὅραμα</span> 1 e 2 não pode ser sustentada com segurança, de modo que certamente predomina a ênfase em 1.—Critodemus, astrólogo helenístico, escreveu livro <span class=\"greek\">Ὅρασις</span> em forma de visão [Vett. Val. 150, 11; 329, 18f]; Herm. Wr. 1, 30 <span class=\"greek\">ἀληθινὴ</span> <span class=\"greek\">ὅρ</span>.; Tob 12:19; Zech 10:2; Pel.-Leg. 18, 20), visão (cf. Da 7:1 Theod.; Iren. 4, 28, 3 [Harv. II 296, 16]): <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁρ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17</a>. <span class=\"greek\">ὅρασιν</span> <span class=\"greek\">ἰδεῖν</span> ou <span class=\"greek\">ὁρᾶν</span>, ter uma visão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17</a> (Jo 3:1); Hv 2, 4, 2. Sobre as visões de Hermas: Hv 2, 1, 1; 3, 10, 3ff; 3, 11, 2; 4; 3, 12, 1; 3, 13, 1; 4, 1, 1. Títulos Hv 2; 3; 4.—DELG s.v. <span class=\"greek\">ὁράω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁρατός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁρατός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ὁράω</span>; Hippocr., Pla. e outros; PGrenf I, 47, 14; LXX; TestReub 4:10; 6:12; Just., D. 3, 7; Tat.), adjetivo verbal de <span class=\"greek\">ὁράω</span>, relativo à capacidade de ser visto, visível (com <span class=\"greek\">ἀόρατος</span>; cf. TestReub 6:12; Philo, Op. M. 12, Migr. Abr. 183 <span class=\"greek\">ἀόρατος</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">ὤν</span>; Ar. 13, 8; Tat. 5, 1): <span class=\"greek\">σῶμα</span>, corpo, Dg 6:4. <span class=\"greek\">ἄρχοντες</span>, autoridades, ISm 6:1. Sobre Cristo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀόρατος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ὁρ</span>., o invisível, que por nossa causa se tornou visível, IPol 3:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁρατά</span> (Ps.-Clem., Hom. 2, 7): <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span>, coisas visíveis e invisíveis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:16</a>; cf. ITr 5:2; IRo 5:3.—DELG s.v. <span class=\"greek\">ὁράω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁράω</span> (Hom. e posteriores), imperfeito, 3ª pessoa plural <span class=\"greek\">ἑώρων</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:2</a>, variante de leitura em lugar de <span class=\"greek\">ἐθεώρουν</span>); perfeito <span class=\"greek\">ἑώρακα</span> e <span class=\"greek\">ἑόρακα</span> (ver B-D-F § 68), 3ª pessoa plural <span class=\"greek\">ἑώρακαν</span>, ao lado de <span class=\"greek\">ἑόρακαν</span> e <span class=\"greek\">ἑωράκασιν</span> (Mlt-H. 221); mais-que-perfeito <span class=\"greek\">ἑωράκειν</span>, Hv 2, 1, 3; futuro <span class=\"greek\">ὄψομαι</span>, 2ª pessoa singular <span class=\"greek\">ὄψῃ</span> (W-S. §13, 18). Passiva: 1º futuro <span class=\"greek\">ὀφθήσομαι</span>; 1º aoristo <span class=\"greek\">ὤφθην</span>, forma variante <span class=\"greek\">ὡράθην</span>, Ezk 12:12; 21:29; Da 1:15 Theod.; perfeito, 3ª pessoa singular <span class=\"greek\">ὦπται</span>, Ex 4:1, 5; Hv 3, 1, 2, infinitivo <span class=\"greek\">ὦφθαι</span> ou <span class=\"greek\">ἑωρᾶσθαι</span> (Just.); mais-que-perfeito, 3ª pessoa singular <span class=\"greek\">ὦπτο</span> (Just.). No período bizantino havia um aoristo médio <span class=\"greek\">ὠψάμην</span> (Lob. sobre Phryn. p. 734). Uma forma de subjuntivo correspondente aparece numa passagem do NT, embora não sem variante de leitura: <span class=\"greek\">ὄψησθε</span> (variante <span class=\"greek\">ὄψεσθε</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:28</a>. As funções do aoristo ativo são assumidas por <span class=\"greek\">εἶδον</span> e suas respectivas formas (ver <span class=\"greek\">εἶδον</span>). <span class=\"greek\">βλέπω</span> é usado, na maior parte, para o presente e o imperfeito. Sobre os usos de <span class=\"greek\">ὁράω</span> e <span class=\"greek\">βλέπω</span>, ver Reinhold p. 95ff. A. Transitivo. ① Perceber pelos olhos, avistar, notar. ⓐ Com acusativo de pessoa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:7</a>, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:57</a>; 9:37; 14:9; 16:16f, 19, 22; 20:18 (PPerkins, Int 46, ’92, 31–41), 25, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:20a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7</a>; AcPl Ha 6, 17; <span class=\"greek\">Κλαύδ̣ιε</span> <span class=\"greek\">ὅ̣</span>[<span class=\"greek\">ρα</span> <span class=\"greek\">Παῦλον</span>], 8, 1. <span class=\"greek\">θεὸν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἑώρακεν</span> <span class=\"greek\">πώποτε</span>, ninguém jamais viu Deus (ver PGM 5, 101f, sobre Osíris, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">εἶδε</span> <span class=\"greek\">πώποτε</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:18</a>; cf. 6:46ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:20b</a> (sobre ver a Deus e sua impossibilidade para os mortais, ver WGrafBaudissin, «Gott schauen» in d. atl. Rel.: ARW 18, 1915, 173–239; RBultmann, ZNW 29, 1930, 169–92; EFascher: Marb. Theol. Studien ’31, 1, 41–77).—Também da percepção de seres pessoais que se tornam visíveis de modo transcendente (UPZ 78, 8 [159 a.C.], acerca de sonho no Serapeu: <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">διδύμας</span>; 69, 6; Just., D. 115, 3); sobre a visão de Cristo que Paulo teve, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:1</a>. O acusativo é suprido pelo contexto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:8</a>. Com acusativo do particípio (B-D-F § 416, 1; Rob. 1123.—UPZ 69, 6 [152 a.C.] <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕπνῳ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Μενέδημον</span> <span class=\"greek\">ἀντικείμενον</span> <span class=\"greek\">ἡμῖν</span>; Ex 2:11, 13; TestJob 26, 6; ParJer 9:20; GrBar 1:3; Philo, Leg. All. 3, 38; Just., A I, 10, 1 e outros): <span class=\"greek\">ὄψονται</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ἐρχόμενον</span>, verão o Filho do Homem vindo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:27</a>. <span class=\"greek\">ὄψεσθε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">καθήμενον</span>, vereis o Filho do Homem sentado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.62\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:62</a> (NPerrin, The End-product of the Christian Pesher Trad., NTS 12, ’66, 150–55). ⓑ Com acusativo de coisa: <span class=\"greek\">ὀπτασίαν</span> <span class=\"greek\">ὁρ</span>., ver uma visão (ver <span class=\"greek\">ὀπτασία</span> 1.—SIG 1169, 6; UPZ 68, 6 [152 a.C.] <span class=\"greek\">ἐνύπνια</span> <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">πονηρά</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:22</a>; 24:23. <span class=\"greek\">ὁράσεις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17</a> (Jo 3:1). <span class=\"greek\">ταῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:49</a>. <span class=\"greek\">πάντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:45</a>. <span class=\"greek\">σημεῖα</span>, 6:2, variante de leitura (por <span class=\"greek\">ἐθεώρουν</span>). Ver também Hv 3, 2, 4. Com acusativo do particípio (SIG 685, 75; 1169, 15; Ex 33:10; TestJob 37:8; Just., A I, 53, 9 e outros): <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἀνεῳγότα</span>, o céu aberto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:51</a>.—Hv 3, 8, 9. Com atração do relativo, <span class=\"greek\">ὧν</span> = <span class=\"greek\">τούτων</span> <span class=\"greek\">ἅ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:15</a>. A atração talvez se deva à concisão coloquial na expressão <span class=\"greek\">μάρτυρα</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">τε</span> <span class=\"greek\">εἶδές</span> <span class=\"greek\">με</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ὀφθήσομαί</span> <span class=\"greek\">σοι</span>, testemunha das coisas em que me viste e daquelas em que te aparecerei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:16b</a> (diferentemente MDibelius, Aufsätze zur Apostelgeschichte, ed. HGreeven ’51, 83). Acerca de Deus, <span class=\"greek\">τ</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὁρᾷ</span>, vê todas as coisas, PtK 2 p. 13, 24 (Ar. 4, 1; cf. 13, 8).—<span class=\"greek\">ὁρ</span>. é termo preferido por J quando fala do que o Filho preexistente viu estando com o Pai (JSchneider, D. Christusschau des Joh.-ev. ’35; diferentemente LBrun, D. Gottesschau des joh. Christus: SymbOsl 5, 1927, 1–22): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἑώρακεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:32</a>; cf. versículo 11. <span class=\"greek\">ἃ</span> <span class=\"greek\">ἑώρακα</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span>, o que vi junto do Pai, 8:38 (visto que se trata de testemunhar e falar, o «perceber» também poderia ser compreendido como «ouvir»; aquilo que é ouvido é interpretado como acontecimento. Cf. Diod S 13, 28, 5 <span class=\"greek\">ὁρᾷς</span>; = «ouves [o clamor]?»; escólio sobre Nicander, Ther. 165 <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">οἷα</span> <span class=\"greek\">λέγεις</span>; Polyaenus 7, 14, 2; Ex 20:18 <span class=\"greek\">λαὸς</span> <span class=\"greek\">ἑώρα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνήν</span>, 22; Dt 4:9; também Philo, Migr. Abr. 47; SibOr 8, 125 <span class=\"greek\">βρυγμὸν</span> <span class=\"greek\">ὁρ</span>.). Sobre aquilo que as testemunhas apostólicas viram de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:1</a>–3. Uso absoluto: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἑωρακώς</span>, a testemunha ocular, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:35</a>. ⓒ <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">τινος</span>, perífrase para «ver alguém» (cf. Gen 43:3, 5; 46:30), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:1</a>. <span class=\"greek\">ὁρ</span>. <span class=\"greek\">το</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (= <span class=\"hebrew\" dir=\"rtl\">רָאָה</span> <span class=\"hebrew\" dir=\"rtl\">אֶת־פְּנֵי</span> <span class=\"hebrew\" dir=\"rtl\">י״י</span>), ver o rosto de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:4</a> (<span class=\"greek\">πρόσωπον</span> 1b <span class=\"greek\">α</span>). <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (= <span class=\"hebrew\" dir=\"rtl\">רָאָה</span> <span class=\"hebrew\" dir=\"rtl\">אֶת־כְּבוֹד</span> <span class=\"hebrew\" dir=\"rtl\">י״י</span>), ver a majestade de Deus (Is 66:18f; GkBar 6:12 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:40</a>. Simplesmente <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, ver Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:8</a>. <span class=\"greek\">ὀψόμεθα</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">καθώς</span> <span class=\"greek\">ἐστιν</span>, nós o veremos como ele é, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a> (Maximus Tyr. 11, 11a <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">ὄψει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">τότε</span>, <span class=\"greek\">ἐπειδὰν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">καλῇ</span>). <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, ver o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:14</a>.—Sobre <span class=\"greek\">ἃ</span> <span class=\"greek\">ἑόρακεν</span> <span class=\"greek\">ἐμβατεύων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>, ver <span class=\"greek\">ἐμβατεύω</span>. ⓓ Passiva em sentido ativo: tornar-se visível, aparecer (Ael. Aristid. 51, 22 K.=27 p. 539 D.: <span class=\"greek\">ὤφθη</span> <span class=\"greek\">τοιάδε</span>; LXX), em sentido absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:19</a>; 12:1, 3; com <span class=\"greek\">τινί</span>, a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:3</a>. <span class=\"greek\">ὅραμα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Παύλῳ</span> <span class=\"greek\">ὤφθη</span>, uma visão apareceu a Paulo durante a noite, 16:9 (Jos., Ant. 2, 70 <span class=\"greek\">τὰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">ὀφθέντα</span>).—Sobre pessoas que aparecem naturalmente (Appian, Syr. 21 §96 <span class=\"greek\">ὤφθησαν</span> = «fizeram uma aparição», Bell. Civ. 2, 130 §542; UPZ 145, 5 [164 a.C.]; 3 Km 3:16 <span class=\"greek\">ὤφθησαν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">γυναῖκες</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βασιλεῖ</span>): (<span class=\"greek\">Μωϋσῆς</span>) <span class=\"greek\">ὤφθη</span> <span class=\"greek\">αὐτοῖς</span>, (Moisés) lhes apareceu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:26</a>. Principalmente sobre seres que aparecem de maneira transcendente, quase sempre com dativo da pessoa a quem aparecem: Deus (Gen 12:7; 17:1 [cf. 1QapGen 22:27: Deus aparece a Abraão]; PGM 4, 3090 <span class=\"greek\">ἕως</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὀφθῇ</span>; ParJer 7:20; Just., D. 56, 4 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2</a>; anjos (Ex 3:2; Judg 6:12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:11</a>; 22:43 (LBrun, ZNW 32, ’33, 265–76); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:30</a>, 35; Moisés e Elias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:31</a> (sem dativo nesta passagem: <span class=\"greek\">ὀφθέντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δόξῃ</span>); o Cristo ressuscitado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:17</a>; 13:31; 26:16a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:5</a>–8 (cf. Ox 1 verso, 13; Unknown Sayings, 69–71); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a> (<span class=\"greek\">ὤφθη</span> <span class=\"greek\">ἀγγέλοις</span>: o Cristo triunfante aparece aos poderes angélicos); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:28</a> (Cristo em sua segunda vinda).—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὀφθήσεται</span>, não mais te aparecerá (sobre um desejo mau), Hm 12, 2, 4 (Antig. Car. 11 <span class=\"greek\">ὁρᾶται</span> = «há»; Aristot. em Apollon. Paradox. 39 <span class=\"greek\">ὄφις</span> <span class=\"greek\">ὤφθη</span> = «havia uma serpente»). ② Ver alguém durante uma visita amistosa, visitar (1 Km 20:29; JosAs 22:3): <span class=\"greek\">ὄψομαι</span> <span class=\"greek\">ὑμᾶς</span>, eu vos visitarei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:23</a>. ③ Experimentar uma condição ou acontecimento, experimentar, testemunhar (cf. POxy 120, 4f <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὁρῶντα</span> <span class=\"greek\">αἱαυτὸν</span> [= <span class=\"greek\">ἑαυτὸν</span>] <span class=\"greek\">ἐν</span> <span class=\"greek\">δυστυχίᾳ</span>; JosAs 6:5 <span class=\"greek\">τί</span> … <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὄψομαι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ταλαίπωρο</span>; ver também Just., D. 61, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:22</a> (ver <span class=\"greek\">εἶδον</span> 4). <span class=\"greek\">ζωήν</span>, vida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:36</a> (cf. Lycophron 1019 <span class=\"greek\">βίον</span>; Ps 88:49 <span class=\"greek\">θάνατον</span>). <span class=\"greek\">μείζω</span> <span class=\"greek\">τούτων</span>, coisas maiores do que essas, 1:50. <span class=\"greek\">ὄψεται</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, toda carne verá a salvação de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:6</a> (Is 40:5). ④ Perceber mental ou espiritualmente, compreender (Polystrat. p. 5 <span class=\"greek\">ὁρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λογισμῷ</span>; Simplicius, In Epict. p. 110, 47 Düb. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθές</span>), extensão figurada de 1. ⓐ Com ênfase no aspecto sensorial da percepção, com acusativo do particípio (Diod S 2, 16, 5; 4, 40, 2; Appian, Syr. 14 §55, Bell. Civ. 2, 14 §50; PHib 44, 4 [253 a.C.] <span class=\"greek\">ὁρῶντες</span> <span class=\"greek\">δέ</span> <span class=\"greek\">σε</span> <span class=\"greek\">καταραθυμοῦντα</span>; 4 Macc 4:24; 9:30; Jos., Vi. 373 <span class=\"greek\">ὄντα</span> <span class=\"greek\">με</span> <span class=\"greek\">ὁρ</span>.; Just., A I, 43, 5; Ath. 2, 3), notar, perceber, compreender: <span class=\"greek\">εἰς</span> <span class=\"greek\">χολὴν</span> <span class=\"greek\">πικρίας</span> … <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">σε</span> <span class=\"greek\">ὄντα</span>, percebo que caíste em fel de amargura (isto é, ciúme amargo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:23</a>. <span class=\"greek\">οὔπω</span> <span class=\"greek\">ὁρῶμεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑποτεταγμένα</span>, ainda não vemos todas as coisas sujeitas a ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:8</a>. Seguido de acusativo e infinitivo, Dg 1. Seguido de <span class=\"greek\">ὅτι</span> (M. Ant. 9, 27, 2; Philo, Migr. Abr. 46; Just., D. 23, 3 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:24</a>; 1 Cl 12:8; 23:4; 44:6. Seguido de pergunta indireta, 1 Cl 16:17; 41:4; 50:1; 15:8; Dg 7:8. Seguido de discurso direto, <span class=\"greek\">ὁρᾶτε</span>, 1 Cl 4:7. ⓑ Com ênfase na compreensão cognitiva, olhar para ou considerar: <span class=\"greek\">ὄψονται</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνηγγέλη</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span>, aqueles a quem não se anunciou (Cristo) o contemplarão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:21</a> (Is 52:15).—Considerar: <span class=\"greek\">ὅρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγγέλου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>, considera as obras do anjo da maldade, Hm 6, 2, 4.—Tomar consciência de: <span class=\"greek\">ὁ</span> <span class=\"greek\">κακοποιῶν</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἐώρακεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>, quem pratica o mal não viu a Deus, 3J 11. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:6</a>. B. Intransitivo. ① Fixar o olhar, olhar, com <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, para alguém (Il. 24, 633; Od. 20, 373; Just., D. 112, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:37</a> (ver <span class=\"greek\">ἐκκεντέω</span>). <span class=\"greek\">ἄνω</span> <span class=\"greek\">ὁρᾶν</span>, olhar para cima, Dg 10:2 (cf. Cicero, De Natura Deorum 2, 140; Ovid, Matamorphoses 1, 85; outras referências EBlakeney, The Epistle to Diognetus ’43, 77f). ② Estar alerta, vigiar, prestar atenção, cuidar para que, seguido de <span class=\"greek\">μή</span> e subjuntivo aoristo (Diod S 27, 17, 3 <span class=\"greek\">ὁρᾶτε</span> <span class=\"greek\">μήποτε</span> <span class=\"greek\">ποιήσωμεν</span>; Epict., Ench. 19, 2; Lucian, Dial. Deor. 8, 2; BGU 37, 5 [50 d.C.]; POxy 532, 15 <span class=\"greek\">ὅρα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἄλλως</span> <span class=\"greek\">πράξῃς</span>; 531, 9 <span class=\"greek\">ὅρα</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">προσκρούσῃς</span>.—B-D-F § 364, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a>; 18:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:15</a>; 1 Cl 21:1; D 6:1.—Com <span class=\"greek\">μή</span> e imperativo (B-D-F § 461, 1; Rob. 996), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:30</a>; 24:6.—Elipticamente (B-D-F § 480, 5; Rob. 949), <span class=\"greek\">ὅρα</span> <span class=\"greek\">μή</span> (subentenda-se <span class=\"greek\">ποιήσῃς</span>), cuidado! não faças isso!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:10</a>; 22:9.—Com <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, ter cautela com algo (B-D-F § 149; Rob. 472): <span class=\"greek\">ὁρᾶτε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζύμης</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Φαρισαίων</span>, tende cuidado e guardai-vos do fermento dos fariseus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:6</a>. <span class=\"greek\">ὁράτε</span>, <span class=\"greek\">βλέπετε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζύμης</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Φαρ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:15</a>. <span class=\"greek\">ὁράτε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φυλάσσεσθε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">πλεονεξίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:15</a>. ③ Assumir a responsabilidade de fazer algo acontecer, cuidar, providenciar: <span class=\"greek\">σὺ</span> <span class=\"greek\">ὄψῃ</span>, vê isso tu mesmo! isso é responsabilidade tua!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:4</a> (Men., Epitr. 493 S. [317 Kö.]; cf. resposta de Tito e declaração de inocência durante a destruição de Jerusalém, Jos., Bell. 6, 215); cf. versículo 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:15</a> (sobre esse latinismo = videris, ver DHesseling em B-D-F § 362; Rob. 109f). Imperativo seguido de futuro imperatival: <span class=\"greek\">ὅρα</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">πάντα</span>, cuida de fazer tudo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (Ex 25:40; cf. 4:21). Seguido de pergunta indireta (Ael. Aristid. 45 p. 121 D.: <span class=\"greek\">ὅρα</span> <span class=\"greek\">τί</span> <span class=\"greek\">ποιεῖς</span>): <span class=\"greek\">ὅρα</span> <span class=\"greek\">τί</span> <span class=\"greek\">μέλλεις</span> <span class=\"greek\">ποιεῖν</span>, atenta para o que estás prestes a fazer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:26</a>, variante de leitura.—B. 1042. Schmidt, Syn. I 244–70. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄργανον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄργανον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Soph., Pla. e outros; papiros, LXX; PsSol 15:3; TestSol 8:2 L; EpArist 101; Philo; Jos., Bell. 2, 230; Just., D. 110, 3 <span class=\"greek\">πολεμικὰ</span> <span class=\"greek\">ὄρ</span>.; Ath.), instrumento, ferramenta: <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, os instrumentos do diabo, 2 Cl 18:2. Lightfoot propôs uma metáfora militar para essa passagem; cf. 2 Macc 12:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:16</a>.—Também acerca do que se utiliza para produzir um acontecimento (por exemplo, madeira para uma estrutura: Pla., Leg. 3, 678d, acerca de instrumentos empregados para cortar madeira; Ps.-Aristot., Mirabilia 108, acerca de ferramentas destinadas ao cavalo de madeira): <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πυρὰν</span> <span class=\"greek\">ἡρμοσμένα</span> <span class=\"greek\">ὄρ</span>., materiais preparados para a pira (funerária), MPol 13:3. Uma vez que a pira já assumira sua forma a partir de madeira reunida (versículo 2), <span class=\"greek\">ὄρ</span>. deve referir-se ao material incendiário colocado ao redor de Policarpo (<span class=\"greek\">αὐτῷ</span> <span class=\"greek\">περιετίθετο</span>) e destinado a produzir chama intensa (para <span class=\"greek\">ἁρμοζω</span> com <span class=\"greek\">πρός</span> no sentido «adequado a, destinado a», cf. Isoc. 2, 34; ver <span class=\"greek\">ἁρμόζω</span> 2, e para a expressão <span class=\"greek\">ἡρμ</span>. <span class=\"greek\">ὄρ</span>., ver 2 Km 6:5, 14).—Figuradamente, os animais da arena como instrumentos por meio dos quais o mártir se torna sacrifício perfeito a Deus, IRo 4:2.—B. 586. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀργή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀργή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hes. e outros, no sentido de «temperamento»; também «ira, indignação, cólera» [assim os trágicos, Hdt. e posteriores]). ① Estado de desagrado relativamente intenso, com ênfase no aspecto emocional, ira, cólera, GPt 12:50 (ver <span class=\"greek\">φλέγω</span> 2). Com <span class=\"greek\">πικρία</span> e <span class=\"greek\">θυμός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:8</a> (sobre a relação entre <span class=\"greek\">ὀργή</span> e <span class=\"greek\">θυμός</span>, frequentemente combinados também na LXX como produto do dualismo hebraico, ver Zenão em Diog. L. 7, 113; Chrysipp. [Stoic. III Fgm. 395]; Philod., De Ira p. 91 W.; PsSol 2:23; ParJer 6:23). Com <span class=\"greek\">διαλογισμοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:8</a>. Com <span class=\"greek\">μερισμός</span>, IPhld 8:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀθέμιτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζήλους</span> <span class=\"greek\">ὀρ</span>., a ira ilegítima causada por ciúme, 1 Cl 63:2. <span class=\"greek\">ἀπέχεσθαι</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ὀρ</span>., abster-se de toda ira, Pol 6:1. <span class=\"greek\">μετ</span>’ <span class=\"greek\">ὀργῆς</span>, com ira (Pla., Apol. 34c; Esth 8:12x; 3 Macc 6:23; JosAs 4:16 <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἀλαζονείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀργῆς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a>; <span class=\"greek\">βραδὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὀρ</span>., tardio em irar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a> (Aristoxenus, Fgm. 56: Sócrates é chamado <span class=\"greek\">τραχὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὀργήν</span>; mas ver Pla., Phd. 116c, onde S. é chamado <span class=\"greek\">πρᾳότατο</span>, «mansíssimo»). <span class=\"greek\">ἐλέγχετε</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀρ</span>., repreendei-vos mutuamente, não com ira, D 15:3 (<span class=\"greek\">ἐν</span> <span class=\"greek\">ὀργῇ</span>, Is 58:13; Da 3:13 Theod.). A ira <span class=\"greek\">ἄφρονα</span> <span class=\"greek\">ἀναιρεῖ</span>, mata o insensato, 1 Cl 39:7 (Job 5:2); conduz ao homicídio, D 3:2; <span class=\"greek\">δικαιοσύνην</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐργάζεται</span>, não produz a justiça de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:20</a>; origina-se em <span class=\"greek\">θυμός</span> e resulta em <span class=\"greek\">μῆνις</span>, Hm 5, 2, 4.—Plural, acessos de ira (Pla., Euthyphro 7b <span class=\"greek\">ἐχθρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀργαί</span>, Rep. 6, 493a; Maximus Tyr. 27, 6b; 2 Macc 4:25, 40; Jos., Vi. 266), 1 Cl 13:1; IEph 10:2 (B-D-F § 142; W-S. §27, 4d). JStelzenberger, D. Beziehgen der frühchristl. Sittenlehre zur Ethik der Stoa ’33, 250ff. Ver também Ps.-Phocyl. 57f; 63f e anotações de Horst, 153, 155–57. ② Indignação intensa dirigida contra uma falta, com ênfase na retribuição, ira (<span class=\"greek\">Πανὸς</span> <span class=\"greek\">ὀργαί</span>, Eur., Med. 1172; Parmeniscus [III/II a.C.] no escólio sobre Eur., Medea 264 Schw. <span class=\"greek\">τῆς</span> <span class=\"greek\">θεᾶς</span> <span class=\"greek\">ὀργή</span>; Diod S 5, 55, 6 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀργήν</span>, de Afrodite; Philostrat., Vi. Apoll. 6, 29; SIG 1237, 5 <span class=\"greek\">ἕξει</span> <span class=\"greek\">ὀργὴν</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">Διός</span>; OGI 383, 210 [I a.C.]; LXX; En 106:15; TestReub 4:4; ApcEsdr 1:17 p. 25, 11 Tdf.; ApcrEzk pap. Fgm. 1 anverso, 6 [Denis, p. 125]; SibOr 4, 162; 5, 75f; Philo, Somn. 2, 179, Mos. 1, 6; Just., D. 38, 2; 123, 3; frequentemente Jos., por exemplo Ant. 3, 321; 11, 127; Theoph. Ant. 1, 3 [p. 62, 21].—EpArist 254 <span class=\"greek\">θεὸς</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">ἁπάσης</span>). Como reação divina ao mal (<span class=\"greek\">παιδεύει</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καλουμένη</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Orig., C. Cels. 4, 72, 4), é concebida não tanto como emoção (<span class=\"greek\">οὐ</span> <span class=\"greek\">πάθος</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">αὐτὴν</span> [subentenda-se <span class=\"greek\">ὀργὴν</span>] <span class=\"greek\">εἶναί</span> <span class=\"greek\">φαμεν</span>, Orig., C. Cels. 4, 72, 1), mas como resultado de uma disposição indignada, juízo, já conhecido da história do AT (acerca dos habitantes de Nínive, <span class=\"greek\">οἳ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">ἐκώλυσαν</span>, evitaram a ira pelo arrependimento, Did., Gen. 116, 22); às vezes manifesta-se no presente, porém mais frequentemente é esperado no futuro como acerto definitivo de Deus com o mal (<span class=\"greek\">ὀρ</span>. é sentimento legítimo do juiz; ver RHirzel, Themis 1907, 416; Pohlenz [ver abaixo, b, fim] 15, 3; Synes. Ep. 2 p. 158b).—Ver Cat. Cod. Astr. V/4 p. 155. ⓐ Acerca do passado e presente: sobre o julgamento da geração do deserto, <span class=\"greek\">ὤμοσα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀργῇ</span> <span class=\"greek\">μου</span>, jurei em minha ira (Ps 94:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:11</a>; 4:3. No presente, sobre os judeus, <span class=\"greek\">ἔφθασεν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀρ</span>., a indignação (<span class=\"greek\">ὀργή</span> em sentido absoluto = <span class=\"greek\">ὁρ</span>. <span class=\"greek\">θεοῦ</span>, também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:19</a> — AvanVeldhuizen, «Geeft den toorn plaats» [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:19</a>]: TSt 25, 1907, 44–46; [sobre 13:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:10</a>]. De maneira semelhante, Jos., Ant. 11, 141) os alcançou, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:16</a> (cf. TestLevi 6:11; sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13</a>–16, ver BPearson, HTR 64, ’71, 79–94). Da indignação de Deus contra o pecado no presente: <span class=\"greek\">ἀποκαλύπτεται</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἀσέβειαν</span>, revela-se a ira de Deus contra toda impiedade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:18</a> (JCampbell, ET 50, ’39, 229–33; SSchultz, TZ 14, ’58, 161–73). Sobre a indignação divina contra malfeitores manifestada nos julgamentos de autoridades governamentais terrenas, 13:4f (aqui <span class=\"greek\">ὀρ</span>. também poderia significar «punição», como Demosth. 21, 43). A ira de Deus permanece como um peso opressivo sobre quem não crê no Filho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:36</a> (para <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">μένει</span>, cf. Wsd 18:20). Da ira do Senhor contra cristãos apóstatas, Hv 3, 6, 1. O Senhor <span class=\"greek\">ἀποστρέφει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, desvia a indignação (divina) de alguém (<span class=\"greek\">ἀποστρέφω</span> 2a), Hv 4, 2, 6.—Da ira do anjo de arrependimento de Deus, Hm 12, 4, 1. ⓑ Sobre o julgamento futuro de Deus, expressamente caracterizado como punitivo (<span class=\"greek\">ἐκφυγεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, escapar da ira e do juízo de Deus, Theoph. Ant. 2, 14 [p. 136, 16]): <span class=\"greek\">ἔσται</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λαῷ</span> <span class=\"greek\">τούτῳ</span>, haverá ira contra este povo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:23</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span> <span class=\"greek\">ὀρ</span>., a ira vindoura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:7</a>; IEph 11:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐρχομένη</span>, a ira que vem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:6</a>. <span class=\"greek\">σωθησόμεθα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀρ</span>., seremos salvos da ira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:9</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔθετο</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὀρ</span>., Deus não nos destinou ao julgamento punitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:9</a>. <span class=\"greek\">θησαυρίζειν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ὀργήν</span>, acumular para si ira (ver <span class=\"greek\">θησαυρίζω</span> 2b e PLond VI 1912, 77–78 <span class=\"greek\">ταμιευόμενος</span> <span class=\"greek\">ἐμαυτῷ</span> … <span class=\"greek\">ὀργήν</span> e 81 <span class=\"greek\">εἰς</span> <span class=\"greek\">ὀργὴν</span> <span class=\"greek\">δικαίαν</span> [em oposição à hostilidade interna, linha 80]; ver SLösch, Epistula Claudiana 1930, 8. Cláudio reserva a si medidas punitivas contra os líderes de uma agitação civil; o paralelo é apenas formal: em nossa passagem são os pecadores que asseguram contra si mesmos a indignação divina), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:5a</a>. Essa ira acumulada se manifestará <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ὀργῆς</span>, no dia da ira (ver <span class=\"greek\">ἡμέρα</span> 3b <span class=\"greek\">β</span>), versículo 5b. Em outros lugares, a apresentação da ira de Deus em Paulo também é predominantemente escatológica: <span class=\"greek\">ὀρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">θυμός</span> (ver <span class=\"greek\">θυμός</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:8</a> (cf. 1QS 4:12); cf. 1 Cl 50:4; <span class=\"greek\">δότε</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρ</span>., dai lugar à ira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:19</a> (ver 2a acima; <span class=\"greek\">τόπος</span> 4). Cf. 9:22a. <span class=\"greek\">ἐπιφέρειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀργήν</span>, infligir punição, 3:5 (ver 13:4f em a acima; ver Just., A I, 39, 2). Os seres humanos são <span class=\"greek\">τέκνα</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">ὀργῆς</span>, por natureza filhos da ira, isto é, sujeitos à indignação divina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a> (JMehlman, Natura Filii Irae etc. ’57). <span class=\"greek\">τέκνα</span> <span class=\"greek\">ὀργῆς</span>, AcPlCor 2:19 (sobre adversários gnósticos de Paulo). Cf. <span class=\"greek\">σκεύη</span> <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">κατηρτισμένα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπώλειαν</span>, vasos de ira preparados para destruição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:22b</a>. Sobre a Lei: <span class=\"greek\">ὀργὴν</span> <span class=\"greek\">κατεργάζεται</span>, ela produz (somente) ira, 4:15.—Em Rv, o vocábulo também serve para expressar pensamentos escatológicos, 6:16; 11:18. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">αὐτῶν</span>, o grande dia da ira deles (de Deus e do Cordeiro; ver acima), 6:17. Sobre <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">αὐτοῦ</span>, o cálice da sua ira, 14:10, e <span class=\"greek\">οἶνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, 16:19; 19:15, ver <span class=\"greek\">θυμός</span> 1 e 2 (AHanson, The Wrath of the Lamb, ’57, 159–80).—ARitschl, Rechtfertigung u. Versöhnung II 4 1900, 119–56; MPohlenz, Vom Zorne Gottes 1909; GWetter, D. Vergeltungsgedanke bei Pls1912; GBornkamm, D. Offenbarung des Zornes Gottes (Ro 1–3): ZNW 34, ’35, 239–62; ASchlatter, Gottes Gerechtigkeit ’35, 48ff; GMacGregor, NTS 7, ’61, 101–9; JHempel, Gottes Selbstbeherrschung, H-WHertzberg Festschr., ’65, 56–66. Ver também <span class=\"greek\">κρίσις</span>, final: Braun 41ff e Filson.—B. 1134. DELG 1 <span class=\"greek\">ὀργή</span>. M-M. DLNT 1238–41. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀργίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀργίζω</span> (<span class=\"greek\">ὀργή</span>; ativa em Aristoph., X., Pla. e outros; Job 12:6, variante de leitura; Pr 16:30, variante de leitura); em nossa literatura, somente na passiva (Soph., Thu. e posteriores; SIG 1170, 5; UPZ 144, 3 [II a.C.]; LXX, En; PsSol 7:5; TestSol 5:6 L; TestJob 34:2; Test12Patr; JosAs 25:8 [<span class=\"greek\">ὀργίσθησαν</span>]; ParJer 9:21; GrBar; ApcMos, Philo, Joseph., Just., Tat., Ath.): <span class=\"greek\">ὀργίζομαι</span>, 1º futuro <span class=\"greek\">ὀργισθήσομαι</span> (LXX); 1º aoristo <span class=\"greek\">ὠργίσθην</span>, particípio <span class=\"greek\">ὀργισθείς</span>, ficar irado, com dativo de pessoa (Diod S 10, 7, 4; Ael. Aristid. 38 p. 721 D.; Ps 84:6; Is 12:1; En 18:16; JosAs 25:8; GrBar 9:7; ApcMos 8; Jos., Ant. 4, 130; 16, 263; Just., D. 136, 1; sobre Deus: Theoph. Ant. 1, 3 [p. 62, 22]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a>; AcPl Ha 3, 2. Seguido de dativo de pessoa e <span class=\"greek\">ὅτι</span>, ficar irado contra alguém porque, Hv 1, 1, 6 (para <span class=\"greek\">ὅτι</span>, cf. Arrian, Anab. 4, 23, 5; 3 Km 11:9; TestZeb 7:11). <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">ἕνεκά</span> <span class=\"greek\">τινος</span>, ficar irado contra alguém por causa de algo (Jos., Ant. 12, 221), 1, 3, 1a. <span class=\"greek\">διά</span> <span class=\"greek\">τι</span>, por alguma coisa, ibidem b (cf. X., An. 1, 2, 26). <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, ficar irado com alguém ou contra alguém (Andoc. 5, 10; Lysias 28, 2; Num 31:14; TestSim 2:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:17</a> (B-D-F § 196; ver Rob. 605). Uso absoluto (X., Hell. 4, 8, 30; Aelian, VH 12, 54; TestJob 34:2; TestLevi 6:6; ParJer 9:21; Jos., Ant. 6, 222; Tat. 10, 1; Ath. 18, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:34</a>; 22:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:41</a>, variante de leitura (em lugar de <span class=\"greek\">σπλαγχνισθείς</span>.—Sobre a variante <span class=\"greek\">ὀργισθείς</span>, ver CTurner, JTS 28, 1927, 145–58); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:21</a>; 15:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a> (cf. Ps 98:1); GJs 22:1; 23:2; AcPl Ha 1, 21; 6, 22. <span class=\"greek\">ὀργίζεσθε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἁμαρτάνετε</span>, irai-vos, mas não pequeis (Ps 4:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:26</a>.—DELG s.v. <span class=\"greek\">ὀργή</span>. M-M s.v. <span class=\"greek\">ὀργίζομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀργίλος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀργίλος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀργή</span>; Hippocr.; Pla., Rep. 2, 405c; 411b; X., De Re Equ. 9, 7; Aristot., EN 2, 7, 10; 4, 5, 8 <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀργίλοι</span> <span class=\"greek\">ταχέως</span> <span class=\"greek\">ὀργίζονται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">δεῖ</span>, «os irascíveis não tardam a irar-se, e o fazem com quem não deveriam, por coisas pelas quais não deveriam, e muito além do que deveriam»; Herodian 4, 9, 3; Ps 17:49; Pr 21:19; 22:24; 29:22; TestAbr A 19 p. 101, 5 [Stone p. 50]; Jos., Ant. 19, 19; Ar.; Theoph. Ant. 1, 2 [p. 60, 28]), inclinado à ira, irascível, de temperamento explosivo (com <span class=\"greek\">αὐθάδης</span> e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:7</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνου</span> <span class=\"greek\">ὀρ</span>., não sejas irascível, D 3:2.—Substantivado: <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀρ</span>., impetuosidade, temperamento explosivo: <span class=\"greek\">Πέτρε</span>, <span class=\"greek\">ἀεί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀ</span>. <span class=\"greek\">παράκειται</span>, Pedro, sempre te acompanha a tendência à impetuosidade, GMary 463, 19. Cf. <span class=\"greek\">ὀργιλότης</span>, Hdt. 2, 181; Aristot., EN 4, 5, 1–4; Rhet. 2, 3; Epict., Ench. 42.—DELG s.v. <span class=\"greek\">ὀργή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀργίλως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀργίλως</span>, advérbio de <span class=\"greek\">ὀργίλος</span> (Demosth. 21, 215 e outros; Menand., Dysc. 102; 4 Macc 8:9), iradamente, com ira, Hm 12, 4, 1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀργυιά</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀργυιά</span> (ou <span class=\"greek\">ὄργυια</span>, mas no plural provavelmente <span class=\"greek\">ὀργυιαί</span>; ver Kühner-Bl. I 392f; Mlt-H. 58. Derivado de <span class=\"greek\">ὀρέγω</span>, «estender»; Hom., Hdt. e outros; inscrições; POxy 669, 39; Jos., Bell. 1, 411), <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span>, distância medida pela extensão horizontal dos braços de uma pessoa, braça, calculada em 1.85 metro; termo técnico náutico empregado para medir a profundidade da água (Diod S 3, 40, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:28ab</a>.—DELG s.v. <span class=\"greek\">ὄργυια</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρέγω</span> (na voz ativa, Hom. e outros: «alcançar, estender»), em nossa literatura somente na voz média <span class=\"greek\">ὀρέγομαι</span> (Hom. e outros, literalmente «estender-se, estender a mão»), e apenas em sentido figurado: procurar alcançar objetivo específico, aspirar a, esforçar-se por, desejar (também Just., Tat.; Ath., R. 15 p. 66, 33 e outros); optativo aoristo, 3ª pessoa singular <span class=\"greek\">ὀρεχθείη</span> (Ath., R. 21 p. 74, 29); com genitivo de coisa (Thu. 2, 65, 10; X., Mem. 1, 2, 15; Pla., Rep. 6, 485d, Leg. 7, 807c; Polyb. 5, 104, 7; Diod S 4, 40, 5 <span class=\"greek\">δόξης</span> <span class=\"greek\">ὀρεγόμενος</span>, «ansioso por glória»; Plut. Phoc. 17, 1, Sol. 29, 4; Lucian, Bis Accus. 29; Epict. 2, 1, 10; 3, 26, 13. Frequentemente Philo; Jos., Vi. 70; Just., A I, 12, 5.—B-D-F § 171, 1; Rob. 508): <span class=\"greek\">ἐπισκοπῆς</span> <span class=\"greek\">ὀρ</span>., aspirar ao ofício de supervisão ou episcopado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:1</a> (sobre a combinação de <span class=\"greek\">ὀρέγομαι</span> e <span class=\"greek\">ἐπιθυμέω</span>, cf. EpArist 211). <span class=\"greek\">κρείττονος</span>, desejar uma (pátria) melhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">φιλαργυρία</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">τινες</span> <span class=\"greek\">ὀρεγόμενοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a>, é expressão condensada: aquilo que se deseja é o <span class=\"greek\">ἀργύριον</span>, o dinheiro, e não a <span class=\"greek\">φιλαργυρία</span>, amor ao dinheiro.—DELG. M-M s.v. <span class=\"greek\">ὀρέγομαι</span>. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρεινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρεινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ὄρος</span>), montanhoso, cheio de colinas (assim Hdt. e posteriores; inscrições, papiros, LXX, EpArist, Philo, Joseph.): <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀρεινή</span> (subentenda-se <span class=\"greek\">χώρα</span>, que aparece em Hdt. 1, 110; X., Cyr. 1, 3, 3; SIG 633, 78.—<span class=\"greek\">ἡ</span> <span class=\"greek\">ὀρεινή</span> sozinho, por exemplo em Aristot., HA 5, 28, 4, e frequentemente na LXX; Philo, Aet. M. 63), região montanhosa, terras altas: <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀρ</span>., ir para a região montanhosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:39</a> (cf. Jos., Bell. 4, 451); <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρ</span>., subiu à região montanhosa, GJs 22:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span>, em toda a região montanhosa da Judeia, versículo 65 (Jos., Ant. 5, 128 <span class=\"greek\">ὀρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Χαναναίας</span>; 12, 7 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀρεινῆς</span> <span class=\"greek\">Ἰουδαίας</span>). GJs 16:2, variante de leitura (em lugar de <span class=\"greek\">ἔρημον</span>).—DELG s.v. <span class=\"greek\">ὄρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄρεξις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄρεξις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὀρέγω</span>; Pla. e outros; LXX; Ath. 21, 1 e R. 21 p. 74, 19 e outros; Hippol., Ref. 5, 14, 10), estado de desejo intenso, anseio, desejo; em sua única ocorrência em nossa literatura, emprega-se em sentido desfavorável (Democr., Fgm. 219; Epicurus p. 161, 26 Us.; Lucian, Tyr. 4 <span class=\"greek\">τὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡδονῶν</span> <span class=\"greek\">ὀρέξεις</span> <span class=\"greek\">χαλιναγωγεῖν</span>; Herodian 3, 13, 6; Herm. Wr. 12, 4; Sir 23:6; Philo.—Acerca do desejo sexual, Jos., Ant. 7, 169; Ps.-Clem., Hom. 3, 68; Orig., C. Cels. 3, 56, 24): <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄρσενες</span> … <span class=\"greek\">ἐξεκαύθησαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀλλήλους</span>, os homens … inflamaram-se em seu desejo uns pelos outros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:27</a>.—DELG s.v. <span class=\"greek\">ὀρέγω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθοποδέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθοποδέω</span> (<span class=\"greek\">ὀρθόπους</span> [<span class=\"greek\">ὀρθός</span>, <span class=\"greek\">πούς</span>]; Soph. e outros; cf. Nicander, Alexiph. 419 [II a.C.] <span class=\"greek\">ὀρθόποδες</span> <span class=\"greek\">βαίνοντες</span>.—<span class=\"greek\">ὀρθοποδία</span> = «progresso»: Papiri della Univers. di Milano, ed. AVogliano nº 24, 8 [117 d.C.]), significado básico «andar direito, ereto», por extensão figurada, agir corretamente, proceder de maneira franca: <span class=\"greek\">ὀρθοποδεῖν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span>, proceder corretamente em relação à verdade do evangelho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a> (cf. OGI 48, 9 <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">ἀναστρεφομένους</span> [restituição segura]). Talvez, porém, progredir, avançar na direção da verdade (CRoberts, JTS 40, ’39, 55f; também JWinter, HTR 34, ’41, 161f, com base em papiro inédito da coleção Michigan [nº 337: III d.C.] <span class=\"greek\">ὀρθοποδεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span>, «a criança está progredindo, crescendo»).—GKilpatrick, NT Studien f. RBultmann ’54, 269–74 («não estavam no caminho certo rumo à verdade do evangelho»; inclui levantamento elucidativo).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Hom. e posteriores), superlativo <span class=\"greek\">ὀρθότατος</span> (EpilMosq 2). ① Relativo ao que está numa linha ou direção reta, em contraste com algo torto, reto. ⓐ Direito, vertical, ereto (Hom. e outros; inscrições, papiros, LXX; Jos., Ant. 20, 67; Just., A I, 55, 4): <span class=\"greek\">ἀνάστηθι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόδας</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὀρθός</span>, põe-te de pé, ereto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:10</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">τρίχες</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὀρθαί</span>, meus cabelos ficaram em pé, Hv 3, 1, 5 (Ael. Aristid. 48, 33 K.=24 p. 474 D.: <span class=\"greek\">τρίχες</span> <span class=\"greek\">ὀρθαί</span>).—Em imagem acerca do corpo ressuscitado (símile do grão de trigo): <span class=\"greek\">σῶμα</span> … <span class=\"greek\">πολλοστὸν</span> <span class=\"greek\">ὀρθὸν</span> <span class=\"greek\">ηὐλογήμενον</span>, corpo … fecundo, ereto, abençoado, AcPl Cor 2:27. ⓑ Reto, em linha reta (Hes. e outros; LXX): <span class=\"greek\">τροχιαὶ</span> <span class=\"greek\">ὀρ</span>., veredas retas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:13</a> (Pr 4:26). Sobre caminho (Theognis, Soph. e outros; Pr 12:15; 16:25; Philo; Jos., Ant. 6, 13), figuradamente (Aesop, Fab. 287 P.=Babr. 8 Cr. e L-P. [estrada]; Philo, Fuga 131 e outros): <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἔχει</span>, a justiça tem caminho reto, Hm 6, 1, 2a (cf. PGrad 4, 9 <span class=\"greek\">ὀρθῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαίως</span>). <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρ</span>. <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">πορεύεσθαι</span>, andar pelo caminho reto, 6, 1, 2b; cf. 4 (Just., D. 8, 2). ② Relativo ao que está de acordo com uma crença ou doutrina, correto, verdadeiro, extensão figurada de 1 (Pind., Hdt. e outros; LXX; TestBenj 3:2; EpArist 244; Just., A II, 2, 2 e D. 3, 3): <span class=\"greek\">συγγράμματα</span> <span class=\"greek\">κάλλιστα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀρθότατα</span>, escritos belíssimos e corretíssimos, EpilMosq 2. <span class=\"greek\">γνώμη</span> <span class=\"greek\">ὀρ</span>., opinião correta, IEph 1:1, variante de leitura (cf. <span class=\"greek\">φρόνημα</span> <span class=\"greek\">ὀρθόν</span>, Polemo B 12 p. 136 Reader; ver também p. 270).—B. 896. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθοτομέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθοτομέω</span> (<span class=\"greek\">ὀρθός</span>, <span class=\"greek\">τέμνω</span>), encontrado independentemente do NT apenas em Pr 3:6; 11:5, onde ocorre com <span class=\"greek\">ὁδούς</span> e claramente significa «abrir caminho em linha reta» ou «cortar uma estrada reta através do terreno» (florestado ou de difícil passagem), para que o viajante siga diretamente ao seu destino (cf. Thu. 2, 100, 2 <span class=\"greek\">ὁδοὺς</span> <span class=\"greek\">εὐθείας</span> <span class=\"greek\">ἔτεμε</span>; Hdt. 4, 136 <span class=\"greek\">τετμημένη</span> <span class=\"greek\">ὁδός</span>; Pla., Leg. 7, 810e; Plut., Galba 24, 7; Jos., C. Ap. 1, 309). Assim, <span class=\"greek\">ὀρθοτομεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> provavelmente significa conduzir a palavra da verdade por caminho reto (como estrada que leva diretamente ao destino), sem desviar-se por discussões prolixas ou conversas ímpias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:15</a>. Para outras propostas, como ensinar corretamente a palavra, expô-la com solidez, estruturá-la de maneira adequada e pregá-la destemidamente, ver M-M.—DELG s.v. <span class=\"greek\">τέμνω</span>. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0258-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρθόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρθόω</span> (<span class=\"greek\">ὀρθός</span>), futuro, 3ª pessoa singular <span class=\"greek\">ὀρθώσει</span>, Sir 27:14; 1º aoristo <span class=\"greek\">ὤρθωσα</span>. Passiva: aoristo <span class=\"greek\">ὠρθώθην</span>, LXX; perfeito, 3ª pessoa singular <span class=\"greek\">ὤρθωται</span>, Esth 7:9; particípio <span class=\"greek\">ὠρθώμενος</span>, 2 Esdr 6:11 (Hom. e outros; LXX; PsSol 10:3; Philo), colocar direito, erguer: <span class=\"greek\">σταυρόν</span>, uma estaca, GPt 4:11 (cf. de um mastro, Lucian, Catapl. 1; <span class=\"greek\">ξύλον</span> = forca, Esth 7:9).—DELG s.v. <span class=\"greek\">ὀρθός</span>.</p></section></article>"};
